package com.aistock.market.marketrefs;
import com.aistock.common.*;import com.aistock.market.security.*;import com.aistock.market.adminquery.AdminMarketDataAccessFilter;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.Cookie;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class MarketVersionReferenceHttpTest {
 final String path="/api/v1/admin/market-data/SH600030/versions/11111111-1111-1111-1111-111111111111/references";SessionIdentityClient identity;MarketVersionReferenceService service;MockMvc mvc;
 @BeforeEach void init(){identity=mock(SessionIdentityClient.class);service=mock(MarketVersionReferenceService.class);when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity("00000000-0000-0000-0000-000000000001","ADMIN",false,1),"t"));mvc=MockMvcBuilders.standaloneSetup(new MarketVersionReferenceController(service)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new AdminMarketDataAccessFilter(identity,"test",new ObjectMapper())).build();}
 @Test void authenticatesAdminAndRejectsOrdinaryAndAnonymous()throws Exception{mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","a"))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity("00000000-0000-0000-0000-000000000001","USER",false,1),"t"));mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","u"))).andExpect(status().isForbidden());verify(service,times(1)).inspect(anyString(),anyString());}
 @Test void rejectsQueriesBodyAndMethodsBeforeInspection()throws Exception{var cookie=new Cookie("AISTOCK_SESSION","a");mvc.perform(get(path).cookie(cookie).param("x","1")).andExpect(status().isBadRequest());mvc.perform(get(path).cookie(cookie).content("{}")).andExpect(status().isBadRequest());mvc.perform(post(path).cookie(cookie)).andExpect(status().isNotFound());verifyNoInteractions(service);}
}
